// The stand-in for the preview site's service worker (lane Site r4). After the swap, the site's
// pages are at the root and one worker there (sw.js) covers everything. A visitor whose browser
// still holds the old worker (scope site/) gets this file instead of the old one at the next
// update check: it deletes the old worker's caches, unregisters itself and reloads the open pages
// so they come from the network (and the redirects in site/ send them to the new addresses).
// Leave it in place for at least one release. Generated by tools/site-build.mjs.

self.addEventListener("install", () => self.skipWaiting());

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys()) {
        if (key.startsWith("splashery-site-")) await caches.delete(key);
      }
      await self.registration.unregister();
      for (const client of await self.clients.matchAll({ type: "window" })) {
        try {
          await client.navigate(client.url);
        } catch {
          // a page that can't be reloaded from here keeps what it has until the next visit
        }
      }
    })(),
  );
});

// No fetch handler: until it is gone, every request goes to the network.
